"""
PAC-MAN  -  a beginner-friendly version made with Python + Pygame
==================================================================
Controls : Arrow keys or W/A/S/D -> move Pac-Man
           P -> pause     M -> mute/unmute     R -> restart     ESC -> quit

Features
--------
* BFS (Breadth-First Search) ghost AI  - red & pink ghosts take the SHORTEST path
* Random-walk AI                       - orange ghost, and scared ghosts
* Screen-wrapping tunnel               - leave through the left/right edge of row 9
* Sound effects                        - generated by code, no sound files needed
* High score                           - saved in "highscore.txt" next to this script
"""

import array
import math
import random
import sys
from collections import deque
from pathlib import Path

import pygame

# ----------------------------------------------------------------------
# 1. SETTINGS
# ----------------------------------------------------------------------
TILE = 30            # size of one grid square in pixels
HUD = 50             # space at the top for score / lives
FPS = 60

PACMAN_SPEED = 6.5   # tiles per second
GHOST_SPEED = 5.5
POWER_TIME = 6.0     # seconds ghosts stay scared after a power pellet

SAMPLE_RATE = 22050
HIGHSCORE_FILE = Path(__file__).with_name("highscore.txt")

# Maze legend:  # wall   . dot   o power pellet   P pac-man start
#               G ghost start    (space) empty floor
# Row 9 has OPEN edges (spaces at both ends) -> that's the wrap-around tunnel.
LAYOUT = [
    "###################",
    "#........#........#",
    "#o##.###.#.###.##o#",
    "#.................#",
    "#.##.#.#####.#.##.#",
    "#....#...#...#....#",
    "####.### # ###.####",
    "####.# G G G #.####",
    "####.# ## ## #.####",
    " ................. ",
    "#.##.#.#####.#.##.#",
    "#o.#.#...P...#.#.o#",
    "#....#...#...#....#",
    "#.##.###.#.###.##.#",
    "#.................#",
    "###################",
]

ROWS = len(LAYOUT)
COLS = len(LAYOUT[0])
WIDTH = COLS * TILE
HEIGHT = ROWS * TILE + HUD

# Directions are (dx, dy) pairs. y grows DOWNWARD on the screen.
UP, DOWN, LEFT, RIGHT = (0, -1), (0, 1), (-1, 0), (1, 0)
DIRS = [UP, DOWN, LEFT, RIGHT]
STOP = (0, 0)

# Colours (R, G, B)
BLACK = (0, 0, 0)
WALL_FILL = (20, 20, 120)
WALL_EDGE = (60, 90, 255)
YELLOW = (255, 220, 0)
WHITE = (255, 255, 255)
DOT_COLOR = (255, 200, 160)
SCARED = (40, 60, 220)
RED = (255, 50, 50)
PINK = (255, 150, 200)
ORANGE = (255, 170, 40)


def step(pos, d):
    """The tile you reach by moving one step `d` from `pos`.
    The column wraps around (column -1 becomes the last column) - that's the tunnel."""
    return ((pos[0] + d[0]) % COLS, pos[1] + d[1])


# ----------------------------------------------------------------------
# 2. HIGH SCORE (saved in a tiny text file)
# ----------------------------------------------------------------------
def load_high_score():
    try:
        return int(HIGHSCORE_FILE.read_text().strip())
    except (OSError, ValueError):
        return 0                      # no file yet (or unreadable) -> start at 0


def save_high_score(value):
    try:
        HIGHSCORE_FILE.write_text(str(value))
    except OSError:
        pass                          # e.g. read-only folder: just skip saving


# ----------------------------------------------------------------------
# 3. SOUND (built from maths - no .wav files required)
# ----------------------------------------------------------------------
def tone(f_start, f_end, duration, volume=0.25, rate=SAMPLE_RATE):
    """Make a square-wave beep whose pitch slides from f_start to f_end (Hz)."""
    n = int(rate * duration)
    samples, phase = [], 0.0
    for i in range(n):
        freq = f_start + (f_end - f_start) * i / n      # current pitch
        phase += 2 * math.pi * freq / rate              # advance the wave
        wave = 1.0 if math.sin(phase) >= 0 else -1.0    # square wave
        fade = 1 - i / n                                # fade out to avoid clicks
        samples.append(int(32767 * volume * wave * fade))
    return samples


class Sounds:
    """Creates all sound effects at start-up. If there is no audio device the
    game simply runs silently instead of crashing."""

    def __init__(self):
        self.enabled = True
        self.sounds = {}
        try:
            info = pygame.mixer.get_init()
            if not info or info[1] != -16:
                return
            rate, _, channels = info
            self.sounds = {
                "chomp_a": self.build(tone(520, 330, 0.06), rate, channels),
                "chomp_b": self.build(tone(330, 520, 0.06), rate, channels),
                "pellet": self.build(tone(300, 900, 0.25), rate, channels),
                "eat_ghost": self.build(tone(200, 1000, 0.18) + tone(1000, 1400, 0.1), rate, channels),
                "death": self.build(tone(800, 80, 0.9, 0.3), rate, channels),
                "win": self.build(sum((tone(f, f, 0.13) for f in (523, 659, 784, 1047)), []), rate, channels),
                "start": self.build(sum((tone(f, f, 0.1) for f in (392, 523, 659, 784)), []), rate, channels),
            }
        except pygame.error:
            self.sounds = {}

    @staticmethod
    def build(samples, rate, channels):
        data = array.array("h")
        for s in samples:
            for _ in range(channels):      # copy sample once per audio channel
                data.append(s)
        return pygame.mixer.Sound(buffer=data.tobytes())

    def play(self, name):
        if self.enabled and name in self.sounds:
            self.sounds[name].play()


# ----------------------------------------------------------------------
# 4. THE MAZE
# ----------------------------------------------------------------------
class Maze:
    """Reads LAYOUT once and remembers where walls, dots and start points are."""

    def __init__(self):
        self.walls = set()
        self.dots = set()
        self.pellets = set()
        self.player_start = (1, 1)
        self.ghost_starts = []
        for row, line in enumerate(LAYOUT):
            for col, ch in enumerate(line):
                if ch == "#":
                    self.walls.add((col, row))
                elif ch == ".":
                    self.dots.add((col, row))
                elif ch == "o":
                    self.pellets.add((col, row))
                elif ch == "P":
                    self.player_start = (col, row)
                elif ch == "G":
                    self.ghost_starts.append((col, row))

    def walkable(self, col, row):
        """True if (col,row) is not a wall. Columns wrap around, so an open
        left edge connects to the open right edge (the tunnel)."""
        if not 0 <= row < ROWS:
            return False
        return (col % COLS, row) not in self.walls


# ----------------------------------------------------------------------
# 5. THE PATH-FINDING ALGORITHM  (BFS)
# ----------------------------------------------------------------------
def bfs_first_step(maze, start, goal, banned=None):
    """
    Breadth-First Search on the maze grid.

    BFS explores tiles in rings: all tiles 1 step away, then 2 steps away,
    then 3... so the FIRST time it reaches the goal it has found a shortest
    path. We only need the FIRST move of that path, so every queue entry
    remembers which first move it started with.

    banned = a direction ghosts may not take first (stops 180-degree turns).
    Returns a direction like (1, 0), or None if there is no path.
    """
    if start == goal:
        return None

    queue = deque()          # tiles waiting to be explored (FIFO)
    visited = {start}        # tiles already seen, so we never loop

    for d in DIRS:           # seed the queue with the start tile's neighbours
        if d == banned:
            continue
        nxt = step(start, d)
        if maze.walkable(*nxt) and nxt not in visited:
            visited.add(nxt)
            queue.append((nxt, d))      # (tile, first move that led here)

    while queue:
        tile, first_move = queue.popleft()
        if tile == goal:
            return first_move
        for d in DIRS:
            nxt = step(tile, d)
            if maze.walkable(*nxt) and nxt not in visited:
                visited.add(nxt)
                queue.append((nxt, first_move))
    return None


# ----------------------------------------------------------------------
# 6. MOVING CHARACTERS
# ----------------------------------------------------------------------
class Mover:
    """
    Base class for Pac-Man and ghosts.

    A mover is always on a tile (col,row) and may be sliding toward the
    neighbouring tile. `progress` goes 0 -> 1 during the slide. When it
    reaches 1 the mover has ARRIVED and picks a new direction. That makes
    movement smooth but still locked to the grid.
    """

    def __init__(self, start, speed):
        self.start = start
        self.speed = speed
        self.reset()

    def reset(self):
        self.col, self.row = self.start
        self.dx, self.dy = STOP
        self.progress = 0.0

    @property
    def moving(self):
        return (self.dx, self.dy) != STOP

    def tile(self):
        """The tile the mover is closest to (used for eating & chasing)."""
        if self.progress >= 0.5:
            return step((self.col, self.row), (self.dx, self.dy))
        return (self.col, self.row)

    def pixel_center(self):
        x = ((self.col + self.dx * self.progress + 0.5) * TILE) % WIDTH   # % = tunnel wrap
        y = (self.row + self.dy * self.progress + 0.5) * TILE + HUD
        return x, y

    def advance(self, dt, game):
        if not self.moving:
            self.choose_direction(game)
        if not self.moving:
            return
        self.progress += self.speed * dt
        if self.progress >= 1:                 # arrived at the next tile
            self.col = (self.col + self.dx) % COLS
            self.row += self.dy
            self.progress = 0.0
            self.choose_direction(game)

    def choose_direction(self, game):
        raise NotImplementedError


class Pacman(Mover):
    def __init__(self, start):
        super().__init__(start, PACMAN_SPEED)

    def reset(self):
        super().reset()
        self.want = STOP        # direction the player last asked for
        self.facing = RIGHT     # used only for drawing

    def choose_direction(self, game):
        # Try the wanted direction first, then keep going straight.
        for d in (self.want, (self.dx, self.dy)):
            if d != STOP and game.maze.walkable(self.col + d[0], self.row + d[1]):
                self.dx, self.dy = d
                self.facing = d
                return
        self.dx, self.dy = STOP          # blocked: stand still

    def update(self, dt, game):
        # Allow an instant U-turn in the middle of a tile.
        if self.moving and self.want == (-self.dx, -self.dy):
            self.col = (self.col + self.dx) % COLS
            self.row += self.dy
            self.dx, self.dy = self.want
            self.facing = self.want
            self.progress = 1 - self.progress
        self.advance(dt, game)


class Ghost(Mover):
    """
    Ghost states:
      house      - waiting inside the pen before being released
      chase      - hunting Pac-Man using its personality (kind)
      frightened - scared (blue), wanders randomly, can be eaten
      eaten      - only eyes; uses BFS to run back home
    """

    def __init__(self, start, color, kind, release_delay):
        self.color = color
        self.kind = kind                  # "chaser", "ambusher" or "random"
        self.release_delay = release_delay
        super().__init__(start, GHOST_SPEED)

    def reset(self):
        super().reset()
        self.state = "house"
        self.timer = self.release_delay

    def update(self, dt, game):
        if self.state == "house":
            self.timer -= dt
            if self.timer <= 0:
                self.state = "chase"
            return
        self.speed = {
            "chase": GHOST_SPEED,
            "frightened": GHOST_SPEED * 0.6,
            "eaten": GHOST_SPEED * 2,
        }[self.state]
        self.advance(dt, game)

    # --- the ghost "brain": runs every time a ghost reaches a new tile ---
    def choose_direction(self, game):
        maze = game.maze
        here = (self.col, self.row)
        back = (-self.dx, -self.dy)       # the way we just came from

        # 1) Decide the TARGET tile (None means "wander randomly")
        if self.state == "eaten":
            if here == self.start:        # home again -> revive in the pen
                self.state = "house"
                self.timer = 2.0
                self.dx, self.dy = STOP
                return
            target = self.start
        elif self.state == "frightened":
            target = None
        elif self.kind == "chaser":       # RED: go straight for Pac-Man
            target = game.pacman.tile()
        elif self.kind == "ambusher":     # PINK: aim 4 tiles ahead of Pac-Man
            target = self.ahead_of_pacman(game)
        else:                             # ORANGE: random wanderer
            target = None

        # 2) Possible moves: any open neighbour except turning back
        options = [d for d in DIRS
                   if d != back and maze.walkable(here[0] + d[0], here[1] + d[1])]
        if not options:                   # dead end: turning back is allowed
            options = [back]

        # 3) Pick a move
        chosen = None
        if target is not None:
            chosen = bfs_first_step(maze, here, target, banned=back)   # <- the algorithm
        if chosen is None:
            chosen = random.choice(options)                            # <- random walk
        self.dx, self.dy = chosen

    def ahead_of_pacman(self, game):
        px, py = game.pacman.tile()
        fx, fy = game.pacman.facing
        for n in range(4, -1, -1):        # try 4 tiles ahead, then 3, 2, 1, 0
            t = ((px + fx * n) % COLS, py + fy * n)
            if game.maze.walkable(*t):
                return t
        return (px, py)


# ----------------------------------------------------------------------
# 7. THE GAME
# ----------------------------------------------------------------------
class Game:
    def __init__(self):
        pygame.mixer.pre_init(SAMPLE_RATE, -16, 1, 512)   # must come before init()
        pygame.init()
        pygame.display.set_caption("Pac-Man (Python + Pygame)")
        self.screen = pygame.display.set_mode((WIDTH, HEIGHT))
        self.clock = pygame.time.Clock()
        self.font = pygame.font.Font(None, 30)
        self.big = pygame.font.Font(None, 56)
        self.maze = Maze()
        self.sounds = Sounds()
        self.high = load_high_score()
        self.new_game()

    def new_game(self):
        self.dots = set(self.maze.dots)
        self.pellets = set(self.maze.pellets)
        self.score = 0
        self.record_beaten = False
        self.lives = 3
        self.power_timer = 0.0
        self.freeze = 0.0
        self.paused = False
        self.chomp_toggle = False
        self.state = "playing"           # playing / gameover / win
        self.pacman = Pacman(self.maze.player_start)
        specs = [(RED, "chaser", 0.5), (PINK, "ambusher", 3.0), (ORANGE, "random", 6.0)]
        self.ghosts = [
            Ghost(pos, color, kind, delay)
            for pos, (color, kind, delay) in zip(self.maze.ghost_starts, specs)
        ]
        self.sounds.play("start")

    def reset_positions(self):
        self.pacman.reset()
        for g in self.ghosts:
            g.reset()
        self.power_timer = 0.0
        self.freeze = 1.5

    def add_score(self, points):
        self.score += points
        if self.score > self.high:
            self.high = self.score
            self.record_beaten = True

    def end_game(self, result):
        self.state = result
        self.sounds.play("win" if result == "win" else "death")
        if self.record_beaten:
            save_high_score(self.high)

    # ---------------- input ----------------
    def handle_events(self):
        keymap = {
            pygame.K_UP: UP, pygame.K_w: UP,
            pygame.K_DOWN: DOWN, pygame.K_s: DOWN,
            pygame.K_LEFT: LEFT, pygame.K_a: LEFT,
            pygame.K_RIGHT: RIGHT, pygame.K_d: RIGHT,
        }
        for event in pygame.event.get():
            if event.type == pygame.QUIT:
                self.quit()
            if event.type == pygame.KEYDOWN:
                if event.key == pygame.K_ESCAPE:
                    self.quit()
                elif event.key in keymap:
                    self.pacman.want = keymap[event.key]
                elif event.key == pygame.K_p and self.state == "playing":
                    self.paused = not self.paused
                elif event.key == pygame.K_m:
                    self.sounds.enabled = not self.sounds.enabled
                elif event.key == pygame.K_r and self.state != "playing":
                    self.new_game()

    # ---------------- game logic ----------------
    def update(self, dt):
        if self.state != "playing" or self.paused:
            return
        if self.freeze > 0:
            self.freeze -= dt
            return

        self.pacman.update(dt, self)

        # Eat dots / pellets on the tile Pac-Man is on
        tile = self.pacman.tile()
        if tile in self.dots:
            self.dots.remove(tile)
            self.add_score(10)
            self.chomp_toggle = not self.chomp_toggle
            self.sounds.play("chomp_a" if self.chomp_toggle else "chomp_b")
        if tile in self.pellets:
            self.pellets.remove(tile)
            self.add_score(50)
            self.sounds.play("pellet")
            self.power_timer = POWER_TIME
            for g in self.ghosts:
                if g.state == "chase":
                    g.state = "frightened"

        # Power-up countdown
        if self.power_timer > 0:
            self.power_timer -= dt
            if self.power_timer <= 0:
                for g in self.ghosts:
                    if g.state == "frightened":
                        g.state = "chase"

        for g in self.ghosts:
            g.update(dt, self)

        self.check_collisions()

        if self.state == "playing" and not self.dots and not self.pellets:
            self.end_game("win")

    def check_collisions(self):
        px, py = self.pacman.pixel_center()
        for g in self.ghosts:
            if g.state == "eaten":
                continue
            gx, gy = g.pixel_center()
            if math.hypot(px - gx, py - gy) < TILE * 0.6:
                if g.state == "frightened":
                    g.state = "eaten"
                    self.add_score(200)
                    self.sounds.play("eat_ghost")
                else:
                    self.lives -= 1
                    if self.lives <= 0:
                        self.end_game("gameover")
                    else:
                        self.sounds.play("death")
                        self.reset_positions()
                    return

    # ---------------- drawing ----------------
    def draw(self):
        self.screen.fill(BLACK)
        self.draw_maze()
        self.draw_pacman()
        for g in self.ghosts:
            self.draw_ghost(g)
        self.draw_hud()

        if self.state == "gameover":
            self.message("GAME OVER", self.end_text())
        elif self.state == "win":
            self.message("YOU WIN!", self.end_text())
        elif self.paused:
            self.message("PAUSED", "Press P to resume")
        elif self.freeze > 0 or (not self.pacman.moving and self.pacman.want == STOP):
            self.message("READY!", "Use arrow keys / WASD")
        pygame.display.flip()

    def end_text(self):
        if self.record_beaten:
            return f"NEW HIGH SCORE: {self.high}  -  R to restart"
        return "Press R to restart"

    def draw_maze(self):
        for (c, r) in self.maze.walls:
            rect = pygame.Rect(c * TILE, r * TILE + HUD, TILE, TILE)
            pygame.draw.rect(self.screen, WALL_FILL, rect)
            pygame.draw.rect(self.screen, WALL_EDGE, rect.inflate(-4, -4), 2, border_radius=6)
        for (c, r) in self.dots:
            pygame.draw.circle(self.screen, DOT_COLOR,
                               (c * TILE + TILE // 2, r * TILE + HUD + TILE // 2), 3)
        if (pygame.time.get_ticks() // 250) % 2 == 0:       # blinking pellets
            for (c, r) in self.pellets:
                pygame.draw.circle(self.screen, DOT_COLOR,
                                   (c * TILE + TILE // 2, r * TILE + HUD + TILE // 2), 8)

    def draw_pacman(self):
        cx, cy = self.pacman.pixel_center()
        radius = TILE // 2 - 2
        angle = {RIGHT: 0, DOWN: 90, LEFT: 180, UP: 270}[self.pacman.facing]
        if self.pacman.moving:
            mouth = abs(math.sin(pygame.time.get_ticks() / 90)) * 40
        else:
            mouth = 15
        start, end = angle + mouth, angle + 360 - mouth
        points = [(cx, cy)]
        for i in range(25):                                  # build a "pie" polygon
            a = math.radians(start + (end - start) * i / 24)
            points.append((cx + radius * math.cos(a), cy + radius * math.sin(a)))
        pygame.draw.polygon(self.screen, YELLOW, points)

    def draw_ghost(self, g):
        cx, cy = g.pixel_center()
        r = TILE // 2 - 2
        if g.state != "eaten":
            color = g.color
            if g.state == "frightened":
                flashing = self.power_timer < 2 and (pygame.time.get_ticks() // 200) % 2
                color = WHITE if flashing else SCARED
            pygame.draw.circle(self.screen, color, (cx, cy - 2), r)           # head
            pygame.draw.rect(self.screen, color, (cx - r, cy - 2, 2 * r, r))  # body
            for i in range(3):                                                # wavy feet
                pygame.draw.circle(self.screen, color,
                                   (cx - r + (2 * i + 1) * r / 3, cy + r - 2), r / 3)
        if g.state == "frightened":
            for ex in (-4, 4):
                pygame.draw.circle(self.screen, WHITE, (cx + ex, cy - 3), 2)
        else:
            for ex in (-5, 5):                                                # eyes
                pygame.draw.circle(self.screen, WHITE, (cx + ex, cy - 4), 4)
                pygame.draw.circle(self.screen, (0, 0, 200),
                                   (cx + ex + g.dx * 2, cy - 4 + g.dy * 2), 2)

    def draw_hud(self):
        self.screen.blit(self.font.render(f"SCORE: {self.score}", True, WHITE), (10, 16))
        high = self.font.render(f"HIGH: {self.high}", True, YELLOW)
        self.screen.blit(high, high.get_rect(center=(WIDTH // 2 + 10, HUD // 2)))
        for i in range(self.lives):
            pygame.draw.circle(self.screen, YELLOW, (WIDTH - 20 - i * 26, HUD // 2), 9)
        if not self.sounds.enabled:
            muted = pygame.font.Font(None, 18).render("MUTED", True, (150, 150, 150))
            self.screen.blit(muted, (10, 4))

    def message(self, text, sub=None):
        surf = self.big.render(text, True, YELLOW)
        rect = surf.get_rect(center=(WIDTH // 2, HUD + ROWS * TILE // 2))
        sub_surf = self.font.render(sub, True, WHITE) if sub else None
        box = rect.inflate(60, 70 if sub else 30)
        if sub_surf:
            box.width = max(box.width, sub_surf.get_width() + 40)
            box.centerx = WIDTH // 2
        pygame.draw.rect(self.screen, BLACK, box, border_radius=10)
        pygame.draw.rect(self.screen, WALL_EDGE, box, 2, border_radius=10)
        self.screen.blit(surf, rect)
        if sub_surf:
            self.screen.blit(sub_surf, sub_surf.get_rect(center=(WIDTH // 2, rect.bottom + 22)))

    # ---------------- main loop ----------------
    def run(self):
        while True:
            dt = min(self.clock.tick(FPS) / 1000, 0.05)   # seconds since last frame
            self.handle_events()
            self.update(dt)
            self.draw()

    def quit(self):
        if self.record_beaten:
            save_high_score(self.high)
        pygame.quit()
        sys.exit()


if __name__ == "__main__":
    Game().run()